import os
from datetime import datetime, timedelta
from typing import Dict, List, Tuple, Optional
import boto3
from boto3.session import Session
from botocore.exceptions import ClientError

class CloudWatchMetricComparator:
    def __init__(self, region_name: Optional[str] = None):
        self.region_name = region_name or os.getenv('AWS_REGION', 'us-east-1')
        self.client = boto3.client('cloudwatch', region_name=self.region_name)

    def get_metric_data(
        self,
        namespace: str,
        metric_name: str,
        dimensions: List[Dict[str, str]],
        start_time: datetime,
        end_time: datetime,
        period: int = 300,
        stat: str = 'Average'
    ) -> List[float]:
        try:
            response = self.client.get_metric_data(
                MetricDataQueries=[
                    {
                        'Id': 'm1',
                        'MetricStat': {
                            'Metric': {
                                'Namespace': namespace,
                                'MetricName': metric_name,
                                'Dimensions': dimensions
                            },
                            'Period': period,
                            'Stat': stat,
                        },
                        'ReturnData': True
                    }
                ],
                StartTime=start_time,
                EndTime=end_time
            )

            if response['MetricDataResults'] and response['MetricDataResults'][0]['Values']:
                return response['MetricDataResults'][0]['Values']
            return []
        except ClientError as e:
            print(f"Error fetching metric data: {e}")
            return []

    def compare_metrics(
        self,
        namespace: str,
        metric_name: str,
        dimensions_a: List[Dict[str, str]],
        dimensions_b: List[Dict[str, str]],
        start_time: datetime,
        end_time: datetime,
        period: int = 300,
        stat: str = 'Average'
    ) -> Dict[str, any]:
        values_a = self.get_metric_data(namespace, metric_name, dimensions_a, start_time, end_time, period, stat)
        values_b = self.get_metric_data(namespace, metric_name, dimensions_b, start_time, end_time, period, stat)

        if not values_a or not values_b:
            return {
                'success': False,
                'error': 'Insufficient data for one or both resources',
                'values_a': values_a,
                'values_b': values_b
            }

        avg_a = sum(values_a) / len(values_a) if values_a else 0
        avg_b = sum(values_b) / len(values_b) if values_b else 0

        diff = avg_a - avg_b
        diff_percentage = (diff / avg_b * 100) if avg_b != 0 else float('inf')

        return {
            'success': True,
            'namespace': namespace,
            'metric_name': metric_name,
            'statistic': stat,
            'period_seconds': period,
            'time_range': {
                'start': start_time.isoformat(),
                'end': end_time.isoformat()
            },
            'resource_a': {
                'dimensions': dimensions_a,
                'values': values_a,
                'average': avg_a,
                'sample_count': len(values_a)
            },
            'resource_b': {
                'dimensions': dimensions_b,
                'values': values_b,
                'average': avg_b,
                'sample_count': len(values_b)
            },
            'comparison': {
                'absolute_difference': diff,
                'percentage_difference': diff_percentage,
                'resource_a_higher': diff > 0,
                'resource_b_higher': diff < 0
            }
        }

def compare_two_resources(
    namespace: str,
    metric_name: str,
    dimensions_a: List[Dict[str, str]],
    dimensions_b: List[Dict[str, str]],
    hours_back: int = 24
) -> Dict[str, any]:
    end_time = datetime.utcnow()
    start_time = end_time - timedelta(hours=hours_back)

    comparator = CloudWatchMetricComparator()
    return comparator.compare_metrics(
        namespace=namespace,
        metric_name=metric_name,
        dimensions_a=dimensions_a,
        dimensions_b=dimensions_b,
        start_time=start_time,
        end_time=end_time
    )
